BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT plan(12);
INSERT INTO auth.users(id,email) VALUES('dddddddd-0000-0000-0000-000000000001','m6a@test.local'),('dddddddd-0000-0000-0000-000000000002','m6b@test.local');
INSERT INTO public.works(id,user_id,work_type,title) VALUES('dddddddd-1000-0000-0000-000000000001','dddddddd-0000-0000-0000-000000000001','book','M6 integrity');
INSERT INTO public.records(id,work_id,record_type) VALUES('dddddddd-2000-0000-0000-000000000001','dddddddd-1000-0000-0000-000000000001','edition');
SELECT lives_ok($$SELECT public.begin_upload('dddddddd-0000-0000-0000-000000000001','dddddddd-3000-0000-0000-000000000001','dddddddd-2000-0000-0000-000000000001','{"size":10}')$$,'intent created');
SELECT throws_ok($$SELECT public.begin_upload('dddddddd-0000-0000-0000-000000000001','dddddddd-3000-0000-0000-000000000001','dddddddd-2000-0000-0000-000000000001','{"size":11}')$$,'23514','upload ID already used for a different request','changed intent rejected');
SELECT public.complete_upload('dddddddd-0000-0000-0000-000000000001','dddddddd-3000-0000-0000-000000000001','{"role":"primary","filename":"a.pdf"}','{"bucket":"documents","storage_path":"dddddddd-0000-0000-0000-000000000001/a.pdf","file_size":10,"checksum_sha256":"m6sha","mime_type":"application/pdf","file_format":"pdf","processing_state":"pending"}');
SELECT is((SELECT count(*)::int FROM public.record_assets ra JOIN public.assets a ON a.id=ra.asset_id WHERE a.checksum_sha256='m6sha'),1,'completion linked exactly once');
SELECT is((SELECT count(*)::int FROM public.jobs j WHERE j.idempotency_key LIKE 'extract_text:%' AND j.user_id='dddddddd-0000-0000-0000-000000000001'),1,'completion enqueued exactly once');
SELECT is((public.complete_upload('dddddddd-0000-0000-0000-000000000001','dddddddd-3000-0000-0000-000000000001','{"role":"primary","filename":"a.pdf"}','{}')->>'status'),'created','lost response replays original result');
SELECT throws_ok($$SELECT public.complete_upload('dddddddd-0000-0000-0000-000000000001','dddddddd-3000-0000-0000-000000000001','{"role":"cover","filename":"a.pdf"}','{}')$$,'23514','upload request changed','changed completion rejected');
INSERT INTO public.assets(user_id,bucket,storage_path,file_size,checksum_sha256,mime_type,file_format,created_at)
SELECT 'dddddddd-0000-0000-0000-000000000001','documents','dddddddd-0000-0000-0000-000000000001/'||n||'.pdf',10,'m6-'||n,'application/pdf','pdf',now()-interval '2 days' FROM generate_series(1,201)n;
INSERT INTO public.record_assets(record_id,asset_id) SELECT 'dddddddd-2000-0000-0000-000000000001',id FROM public.assets WHERE checksum_sha256 LIKE 'm6-%' AND checksum_sha256<>'m6-201';
SELECT public.claim_storage_cleanup(100);
SELECT is((SELECT count(*)::int FROM public.storage_deletions d JOIN public.assets a ON a.id=d.asset_id WHERE a.checksum_sha256='m6-201'),1,'orphan beyond 200 linked rows is claimed');
SELECT throws_ok($$INSERT INTO public.record_assets(record_id,asset_id) SELECT 'dddddddd-2000-0000-0000-000000000001',id FROM public.assets WHERE checksum_sha256='m6-201'$$,'23514','asset unavailable or ownership mismatch','relinking a deletion claim is forbidden');
SELECT is((SELECT count(*)::int FROM public.assets WHERE checksum_sha256='m6-201'),1,'claim retains asset until bytes removed');
SELECT public.finish_storage_deletion('documents','dddddddd-0000-0000-0000-000000000001/201.pdf');
SELECT is((SELECT count(*)::int FROM public.assets WHERE checksum_sha256='m6-201'),0,'finished deletion removes row');
UPDATE public.jobs SET available_at=now()+interval '1 day';
INSERT INTO public.jobs(id,user_id,job_type,payload) VALUES('dddddddd-4000-0000-0000-000000000001','dddddddd-0000-0000-0000-000000000001','extract_text',jsonb_build_object('asset_id',(SELECT id FROM public.assets WHERE checksum_sha256='m6sha')));
SELECT public.claim_jobs();
SELECT is(public.finish_job('dddddddd-4000-0000-0000-000000000001',0,'{}'),false,'stale claim cannot finish');
SELECT is(public.finish_job('dddddddd-4000-0000-0000-000000000001',1,'{}'),true,'current claim finishes');
SELECT * FROM finish();
ROLLBACK;
